package practice;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.Charset;
import java.util.function.Consumer;

/** Reads a partner's stock feed: one record per line, in the charset the partner declared. */
public final class FeedLines {

    private FeedLines() {
    }

    /**
     * Hands each line of {@code feed} to {@code line}, in order, and returns how many there were.
     * The caller owns the stream and closes it.
     */
    public static int forEachLine(InputStream feed, Charset charset, Consumer<String> line) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(feed, charset.newDecoder()));
        int count = 0;
        for (String s; (s = reader.readLine()) != null; count++) {
            line.accept(s);
        }
        return count;
    }
}

package practice;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            byte[] utf8 = "Göteborg;14\nŠiauliai;3\nSKU-12;0\n".getBytes(StandardCharsets.UTF_8);
            int count = FeedLines.forEachLine(new ByteArrayInputStream(utf8), StandardCharsets.UTF_8,
                    line -> System.out.println("utf-8 line: " + shown(line)));
            System.out.println("utf-8 lines: " + count);
            byte[] latin1 = "Málaga;8\n".getBytes(StandardCharsets.ISO_8859_1);
            FeedLines.forEachLine(new ByteArrayInputStream(latin1), StandardCharsets.ISO_8859_1,
                    line -> System.out.println("latin-1 line: " + shown(line)));
            try {
                FeedLines.forEachLine(new ByteArrayInputStream(latin1), StandardCharsets.UTF_8,
                        line -> System.out.println("stored: " + shown(line)));
            } catch (IOException refused) {
                System.out.println("latin-1 read as utf-8: " + refused.getClass().getSimpleName());
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    /** The line with each non-ASCII letter written as its code, so it reads the same on any console. */
    private static String shown(String line) {
        StringBuilder out = new StringBuilder();
        for (char c : line.toCharArray()) out.append(c < 128 ? String.valueOf(c) : String.format("\\u%04x", (int) c));
        return out.toString();
    }
}

